#!/usr/bin/env node
/**
 * Executes an institutional page's declared localization loader against a
 * bounded browser-like DOM. The parent validator stays synchronous by running
 * this probe in a short-lived child process; the child can still await the
 * real Promise/fetch path used by browser widgets. The harness records both
 * requests and completed JSON bodies so hard-coded loaders cannot satisfy the
 * visual assertions without consuming every required locale bundle.
 *
 * LATTICE:BEGIN — generated by lib/build-lattice-headers.js from docs/lattice-map.json. Do not hand-edit; edit the JSON and regenerate.
 *   role      : bounded behavioral probe for institutional localization loaders — operates the declared control and observes visible, alt, and ARIA translations
 *   reads     : declared institutional localization widget source (provided by lib/check-institutional-surfaces.js)
 *               required compiled locale bundles (provided by lib/check-institutional-surfaces.js)
 *               active page binding keys and localization-control attribute (provided by lib/check-institutional-surfaces.js)
 *   writes    : stdout JSON only in --probe-child mode
 *   loaded-by : lib/check-institutional-surfaces.js
 *   tested-by : tests/54-institutional-surfaces.test.js
 *
 *   CHANGE MAP — if you touch X here, also check:
 *     DOM or fetch harness contract changes:
 *       - widgets/vex-institutional.js (the later runtime implementation must pass this behavior, not target harness internals)
 *       - tests/54-institutional-surfaces.test.js throwing, no-op, and working loader probes
 *     required observed bindings change:
 *       - lib/check-institutional-surfaces.js pageI18nBindings() and activeLocalizationIssues()
 *       - docs/architecture/18-institutional-pages.md active-page runtime invariant
 * LATTICE:END
 */

'use strict';

const vm = require('vm');
const { spawnSync } = require('child_process');

const CHILD_ARG = '--probe-child';
const PROBE_TIMEOUT_MS = 3000;
const SCRIPT_TIMEOUT_MS = 1000;

function mockElement(attributes = {}, textContent = '') {
  const listeners = new Map();
  return {
    attributes: { ...attributes },
    textContent,
    hidden: true,
    value: attributes.value || '',
    options: [],
    getAttribute(name) {
      return Object.hasOwn(this.attributes, name) ? this.attributes[name] : null;
    },
    setAttribute(name, value) {
      this.attributes[name] = String(value);
    },
    addEventListener(type, listener) {
      if (!listeners.has(type)) listeners.set(type, []);
      listeners.get(type).push(listener);
    },
    dispatchEvent(event) {
      for (const listener of listeners.get(event.type) || []) listener.call(this, event);
      return true;
    },
    querySelector() {
      return null;
    },
    replaceWith() {},
  };
}

function bindingElements(keys, attribute) {
  return (keys || []).map((key, index) => mockElement(
    { [attribute]: key },
    `__vex_before_${attribute}_${index}__`
  ));
}

function expectedText(bundle, key, attribute) {
  const entry = bundle && bundle[key];
  if (!entry || typeof entry !== 'object') return null;
  if (attribute === 'data-i18n-aria') return entry['aria-label'] || entry.text || null;
  return entry.text || null;
}

function observeBinding(element, attribute) {
  if (attribute === 'data-i18n-alt') return element.getAttribute('alt');
  if (attribute === 'data-i18n-aria') return element.getAttribute('aria-label');
  return element.textContent;
}

function makeHarness(input, runtimeErrors) {
  const visible = bindingElements(input.bindings.text, 'data-i18n');
  const alt = bindingElements(input.bindings.alt, 'data-i18n-alt');
  const aria = bindingElements(input.bindings.aria, 'data-i18n-aria');
  for (const element of alt) element.setAttribute('alt', element.textContent);
  for (const element of aria) element.setAttribute('aria-label', element.textContent);

  const select = mockElement({ [input.controlAttribute]: '' });
  select.options = input.requiredLocales.map(locale => mockElement({ value: locale }, locale));
  select.value = input.defaultLocale;

  const documentElement = mockElement({ lang: input.defaultLocale });
  const selectorLists = {
    '[data-i18n]': visible,
    '[data-i18n-alt]': alt,
    '[data-i18n-aria]': aria,
    '[data-vex-route]': [],
  };
  const document = {
    readyState: 'complete',
    documentElement,
    querySelector(selector) {
      const attribute = /^\[([^\]]+)\]$/.exec(selector);
      if (attribute && Object.hasOwn(select.attributes, attribute[1])) return select;
      return null;
    },
    querySelectorAll(selector) {
      return selectorLists[selector] || [];
    },
    addEventListener() {},
    createElement() {
      return mockElement();
    },
  };

  const storage = new Map();
  const location = { pathname: `/pages/${input.slug}.html`, search: '', hash: '' };
  const history = {
    replaceState(_state, _title, next) {
      const parsed = new URL(next, 'https://vextreme.invalid');
      location.pathname = parsed.pathname;
      location.search = parsed.search;
      location.hash = parsed.hash;
    },
  };

  const fetches = { requests: [], completed: [] };

  function fetch(url) {
    const urlText = String(url);
    const request = urlText.split(/[?#]/)[0];
    for (const locale of input.requiredLocales) {
      const suffix = `/data/strings/compiled/scopes/${input.category}/${input.scope}.${locale}.json`;
      if (request.endsWith(suffix) || request.endsWith(suffix.slice(1))) {
        fetches.requests.push({ url: urlText, locale, ok: true, status: 200 });
        return Promise.resolve({
          ok: true,
          status: 200,
          json: () => Promise.resolve(input.bundles[locale]).then(bundle => {
            fetches.completed.push({ url: urlText, locale, ok: true, status: 200 });
            return bundle;
          }),
        });
      }
    }
    fetches.requests.push({ url: urlText, locale: null, ok: false, status: 404 });
    return Promise.resolve({
      ok: false,
      status: 404,
      json: () => Promise.resolve({}).then(bundle => {
        fetches.completed.push({ url: urlText, locale: null, ok: false, status: 404 });
        return bundle;
      }),
    });
  }

  const context = {
    document,
    location,
    history,
    fetch,
    URL,
    URLSearchParams,
    Promise,
    setTimeout,
    clearTimeout,
    localStorage: {
      getItem(key) { return storage.has(key) ? storage.get(key) : null; },
      setItem(key, value) { storage.set(key, String(value)); },
      removeItem(key) { storage.delete(key); },
    },
    matchMedia: () => ({ matches: false }),
    console: {
      log() {},
      warn() {},
      error(...args) { runtimeErrors.push(args.map(String).join(' ')); },
    },
    VEX_STRING_SCOPES: [input.scope],
    VEX_STRING_CATEGORY: input.category,
    VEX_INST_ROOT: '../',
  };
  context.window = context;
  context.self = context;

  return { context, select, documentElement, elements: { text: visible, alt, aria }, fetches };
}

async function settleRuntime() {
  await Promise.resolve();
  await new Promise(resolve => setImmediate(resolve));
  await Promise.resolve();
  await new Promise(resolve => setTimeout(resolve, 10));
}

function bindingFailures(input, elements, locale) {
  const failures = [];
  const bundle = input.bundles[locale];
  for (const [kind, attribute] of [
    ['text', 'data-i18n'],
    ['alt', 'data-i18n-alt'],
    ['aria', 'data-i18n-aria'],
  ]) {
    for (const element of elements[kind]) {
      const key = element.getAttribute(attribute);
      const expected = expectedText(bundle, key, attribute);
      const actual = observeBinding(element, attribute);
      if (actual !== expected) failures.push(`${attribute}=${key} expected ${JSON.stringify(expected)} but observed ${JSON.stringify(actual)}`);
    }
  }
  return failures;
}

async function probeLocalizationRuntime(input) {
  const issues = [];
  const runtimeErrors = [];
  const harness = makeHarness(input, runtimeErrors);
  const context = vm.createContext(harness.context);

  process.on('unhandledRejection', error => runtimeErrors.push(String(error && error.stack || error)));

  try {
    new vm.Script(input.loaderSource, { filename: input.loaderPath })
      .runInContext(context, { timeout: SCRIPT_TIMEOUT_MS });
    await settleRuntime();
  } catch (error) {
    return { issues: [`loader failed during mount: ${error.message}`], fetches: harness.fetches };
  }

  if (harness.select.hidden) issues.push('declared language control remained hidden after loader mount');

  const localesToOperate = input.requiredLocales.filter(locale => locale !== input.defaultLocale);
  for (const locale of localesToOperate) {
    try {
      vm.runInContext(
        `document.querySelector(${JSON.stringify(`[${input.controlAttribute}]`)}).value = ${JSON.stringify(locale)};` +
        `document.querySelector(${JSON.stringify(`[${input.controlAttribute}]`)}).dispatchEvent({ type: 'change' });`,
        context,
        { timeout: SCRIPT_TIMEOUT_MS }
      );
      await settleRuntime();
    } catch (error) {
      issues.push(`${locale} control operation failed: ${error.message}`);
      continue;
    }

    if (harness.documentElement.getAttribute('lang') !== locale) {
      issues.push(`${locale} control did not set <html lang="${locale}">`);
    }
    issues.push(...bindingFailures(input, harness.elements, locale).map(message => `${locale}: ${message}`));
  }

  if (localesToOperate.length) {
    try {
      vm.runInContext(
        `document.querySelector(${JSON.stringify(`[${input.controlAttribute}]`)}).value = ${JSON.stringify(input.defaultLocale)};` +
        `document.querySelector(${JSON.stringify(`[${input.controlAttribute}]`)}).dispatchEvent({ type: 'change' });`,
        context,
        { timeout: SCRIPT_TIMEOUT_MS }
      );
      await settleRuntime();
      if (harness.documentElement.getAttribute('lang') !== input.defaultLocale) {
        issues.push(`return control did not restore <html lang="${input.defaultLocale}">`);
      }
      issues.push(...bindingFailures(input, harness.elements, input.defaultLocale)
        .map(message => `${input.defaultLocale} return: ${message}`));
    } catch (error) {
      issues.push(`${input.defaultLocale} return control failed: ${error.message}`);
    }
  }

  for (const locale of input.requiredLocales) {
    const completed = harness.fetches.completed.some(fetch => fetch.locale === locale && fetch.ok);
    if (!completed) issues.push(`${locale} required bundle fetch did not complete`);
  }

  issues.push(...runtimeErrors.map(error => `runtime error: ${error}`));
  return { issues: [...new Set(issues)], fetches: harness.fetches };
}

function runLocalizationRuntimeProbe(input) {
  const child = spawnSync(process.execPath, [__filename, CHILD_ARG], {
    input: JSON.stringify(input),
    encoding: 'utf8',
    timeout: PROBE_TIMEOUT_MS,
    maxBuffer: 1024 * 1024,
  });
  if (child.error) return { issues: [`runtime probe could not complete: ${child.error.message}`] };
  if (child.status !== 0) {
    const detail = (child.stderr || child.stdout || `exit ${child.status}`).trim();
    return { issues: [`runtime probe process failed: ${detail}`] };
  }
  try {
    const result = JSON.parse(child.stdout);
    return result && Array.isArray(result.issues) ? result : { issues: ['runtime probe returned an invalid result'] };
  } catch (error) {
    return { issues: [`runtime probe returned invalid JSON: ${error.message}`] };
  }
}

async function childMain() {
  let raw = '';
  process.stdin.setEncoding('utf8');
  for await (const chunk of process.stdin) raw += chunk;
  const result = await probeLocalizationRuntime(JSON.parse(raw));
  process.stdout.write(JSON.stringify(result));
}

if (require.main === module && process.argv.includes(CHILD_ARG)) {
  childMain().catch(error => {
    process.stderr.write(String(error && error.stack || error));
    process.exitCode = 1;
  });
}

module.exports = { probeLocalizationRuntime, runLocalizationRuntimeProbe };

// [VXG RealForever]
